"""
Region table for regions 3–15. Each region bundles everything that lives there.
Fields:
  key, name, cn, order, realms (min,max), elem (primary element), scene, desc
  enemies: list of (key, name, cn, kind, elem, look, desc) — first 3 normals, 4th elite, 5th special (human/demonic)
  boss: (key, name, cn, elem, look, desc, weak)
  dungeon: (key, name, cn, kind 'resource'|'challenge', scene, boss(key, name, cn, elem, look, weak))
  mats: herb, ore, monster, crystal — each (key, name, cn, look)
  npc: (key, name, cn, role, look, personality, backstory, line)
  event: (key, name, cn, text, scene, choice_a, choice_b)
  tech: player active (key, name, cn, elem, rarity, desc, power, sp, cd, status, chance)
  etech: enemy-only (key, name, cn, elem, desc, power, status, chance)
  passive: (key, name, cn, elem, rarity, desc, bonuses)
  method: (key, name, cn, elem, rarity, grade, qi_mult, bonuses, desc)
  gear: 3 × (key, name, cn, slot, type, look, signature)
  set: (key, name, cn, desc, bonus2, bonus3) or None
  beasts: list of (key, name, cn, rarity, elem, species, look, desc)
  pill: (key, name, cn, look, desc)
  secret_realm: optional (key, name, cn, scene, boss(key, name, cn, elem, look, weak))
"""

